<?php
declare(strict_types=1);
requirePermission('print');
$stock=($_GET['type']??'')==='stock';
if($stock&&!inventoryEnabled()){http_response_code(403);exit('Lager je isključen.');}if($stock)requirePermission('inventory');else requirePermission('orders');
$o=$stock?null:query('SELECT * FROM orders WHERE id=?',[(int)($_GET['id']??0)])->fetch();
if(!$stock&&!$o){http_response_code(404);exit('Narudžba ne postoji.');}
?><!doctype html><html lang="bs"><head><meta charset="utf-8"><title><?=$stock?'Lagerlista':'Pošiljka #'.$o['id']?></title><link rel="stylesheet" href="assets/style.css"><script src="assets/print.js" defer></script></head><body class="print-page"><div class="no-print"><button id="print-button">Štampaj / sačuvaj PDF</button> <a href="admin.php">Administracija</a></div><main>
<?php if($stock):?><h1>Lagerlista · <?=e(setting('shop_name'))?></h1><p><?=date('d.m.Y. H:i')?></p><table><tr><th>SKU</th><th>Proizvod</th><th>Slobodno</th><th>Rezervisano</th><th>Fizički</th></tr><?php foreach(query('SELECT * FROM products ORDER BY name')->fetchAll() as $p):?><tr><td><?=e($p['sku'])?></td><td><?=e($p['name'])?></td><td><?=$p['stock']?></td><td><?=$p['reserved']?></td><td><?=(int)$p['stock']+(int)$p['reserved']?></td></tr><?php endforeach;?></table>
<?php else:?><h1><?=deliveryType($o)==='pickup'?'List za lično preuzimanje':'List za slanje'?> #<?=$o['id']?></h1><p>Pošiljalac: <?=e(setting('sender_name',setting('shop_name')))?><br><?=nl2br(e(setting('sender_address')))?><br><?=e(setting('sender_phone'))?></p><section class="panel"><h2>Primalac: <?=e($o['customer_name'])?></h2><p><?=e($o['address'])?><br><?=e($o['city'])?><br>Telefon: <?=e($o['phone'])?></p></section><p>Status otpreme: <?=e(orderStatus($o['status']))?> · Naplata: <?=e(paymentLabel($o['payment_status']))?></p><p>Kurir: <?=e(deliveryType($o)==='pickup'||$o['dispatch_method']==='personal'?'Lična predaja':($o['courier_name']??'Upisati pri predaji kuriru'))?><br>Datum otpreme: <?=e((string)($o['dispatched_at']??'Još nije potvrđena'))?></p><p>Dostava: <?=e($o['shipping_method'])?> · Broj pošiljke: <?=e((string)$o['tracking_number'])?></p><?php if($o['planned_delivery_id']):?><p>Pripremljen način: <?=e($o['planned_delivery_name'])?><br>Dogovoreni trošak kurira: <?=money((float)$o['planned_delivery_cost'])?> · <?=e(deliveryPayers()[$o['planned_delivery_payer']]??'')?><br>Uslovi: <?=nl2br(e($o['planned_delivery_terms']))?></p><?php endif;?><p>Uslovi pri kupovini: <?=nl2br(e((string)$o['shipping_terms']))?></p><h2><?=deliveryType($o)==='pickup'?'Za plaćanje pri preuzimanju':'Otkupnina'?>: <?=money($o['payment_method']==='cod'&&$o['payment_status']==='unpaid'&&!in_array($o['status'],['cancelled','returned'],true)?(float)$o['total']:0.0)?></h2><p>Ukupno s dostavom: <?=money((float)$o['total'])?> · Plaćanje: <?=e(deliveryPaymentLabel($o).' / '.$o['payment_status'])?></p><p>Obrazloženje otpreme: <?=nl2br(e((string)$o['dispatch_note']))?></p><p>Napomena: <?=nl2br(e((string)$o['note']))?></p><h2>Lista za pakovanje</h2><table><tr><th>Artikal</th><th>Količina</th><th>Jedinična cijena</th><th>Provjereno</th></tr><?php foreach(query('SELECT * FROM order_items WHERE order_id=?',[$o['id']])->fetchAll() as $item):?><tr><td><?=e($item['product_name'])?></td><td><?=$item['quantity']?></td><td><?=money((float)$item['unit_price'])?></td><td>☐</td></tr><?php endforeach;?></table><p><?=deliveryType($o)==='pickup'?'Interni list za pripremu i ličnu predaju narudžbe kupcu.':'Interni list za pripremu pošiljke. Službenu kurirsku naljepnicu izdaje odabrana kurirska služba.'?></p><?php endif;?></main></body></html>
